import{z as i,x as l,o as r,c as d,q as n,j as B,D as e,d as a,s as o,S as s,b as t}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"监管与制度事件","description":"","frontmatter":{"title":"监管与制度事件","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ed-regulatory-event.md","filePath":"quant/ed-regulatory-event.md","lastUpdated":1791063341000}'),p={name:"quant/ed-regulatory-event.md"};function u(c,E,C,h,g,m){const A=l("Mermaid");return r(),d("div",null,[E[2]||(E[2]=n('<h1 id="监管与制度事件" tabindex="-1">监管与制度事件 <a class="header-anchor" href="#监管与制度事件" aria-label="Permalink to &quot;监管与制度事件&quot;">​</a></h1><div class="epigraph"><p>制度改变的不是某只股票的现金流，而是所有人共同面对的速率方程；它的样本量是 1，机制证据只能来自速率本身。</p><footer>—— 据 Leuz and Wysocki, Journal of Accounting Research, 2016；Harris, Trading and Exchanges, 2003 整理</footer></div><p><a href="/quant/ed-macro-release-event">上一课</a>的载荷未知但时点确定；制度事件连时点也不确定——宣布、征求意见、生效、细则各占一段日历，可相隔数月。本课写监管与制度变化的事件化：tick、费率、撮合迁移、涨跌停参数、借券与减持规则。方法协议已由<a href="/quant/obd-eventstudy-micro">事件研究的微观版本</a>立好；本课写对象面：时间线怎么登记，适用范围怎么分组，合规怎么进事件表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>制度事件与前三类的根本差别是<strong>改写规则本身</strong>：前三类发生在给定规则下，它改变规则下的行为函数。事件化因此多三件事。第一，<strong>时间线三段</strong>：宣布日，预期吸收、行为开始适应；生效日，强制切换；细则日，解释空间收窄。只用生效日做事件窗，会漏掉宣布效应与过渡期，把适应误判为突变。第二，<strong>样本量是 1</strong>：一次制度变化不能重复抽样，统计推断让位于机制证据——系数变化与理论预测的形状核对。第三，<strong>适用范围给出天然对照</strong>：受影响与不受影响的品种同窗对比，是制度事件最干净的设计资源，日历事件反而没有。</p><p><span class="marginnote">术语翻译：「样本量是 1」指制度变化无法重复抽样——某年的熔断机制不会在同样的市场里原样再发生一次。因此不能靠大量重复算平均效应，只能核对机制证据：变化后的系数方向与理论预测的形状是否一致。</span></p><h3 id="四条作用通道" tabindex="-1">四条作用通道 <a class="header-anchor" href="#四条作用通道" aria-label="Permalink to &quot;四条作用通道&quot;">​</a></h3><p>制度通过四条通道起作用：<strong>参与集合</strong>（谁能交易、谁须披露、谁被请出市场）；<strong>交易技术</strong>（tick、费率、撮合、竞价时长）；<strong>头寸约束</strong>（杠杆、卖空、持有期、报备）；<strong>信息环境</strong>（披露义务与频率）。一次变化常同时动几条通道，单一归因从设计上不成立——与<a href="/quant/obd-eventstudy-micro">事件研究的微观版本</a>「复合事件要拆」同源。</p><p><span class="marginnote">直觉类比：把市场想成一条河。制度事件不是往河里扔一块石头（单点冲击），而是改河床本身——谁能下河（参与集合）、水流多急（交易技术）、每人能挑多重的水（头寸约束）、有没有水位公告（信息环境）。</span></p><p><span class="marginnote">Bushee 与 Leuz（2005）：OTCBB 强制披露规则实施后，大量小公司宁可退到粉单甚至注销也不补披露——制度事件先改变参与集合本身，其次才是留在场内的人怎么交易。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>时间线登记。</strong> 事件表加三个时点字段（宣布、生效、细则定稿）与适用范围字段（品种、门槛、豁免）。回测分段按生效时点切，研究分段按宣布时点切——不同时切，会同时错。</p><p><strong>分组对照。</strong> 受影响组与对照组同窗相比，结果变量用微观量：价差、深度、撤单率、定价误差、成交分布的相位。涨跌停参数与竞价安排的对照设计，A 股语境见<a href="/quant/cn-limit-auction">涨跌停与集合竞价</a>。</p><p><strong>合规映射。</strong> 规则改变头寸的合法性与成本：借券暂停使对冲腿消失，减持限制改变退出路径，报备要求改变时延预算。这些不进 alpha 模型，进可行性表——旧规则下成立、新规则下不可实现的策略，研究价值为零。制度事件表因此输出两张表：速率系数表给研究，约束变化表给风控合规。</p>',14)),(r(),B(s,null,{default:e(()=>[o(A,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20ANN%5B%22%E5%AE%A3%E5%B8%83%E6%97%A5%EF%BC%9A%E9%A2%84%E6%9C%9F%E5%90%B8%E6%94%B6%20%E8%BF%87%E6%B8%A1%E8%A1%8C%E4%B8%BA%22%5D%20--%3E%20EFF%5B%22%E7%94%9F%E6%95%88%E6%97%A5%EF%BC%9A%E5%BC%BA%E5%88%B6%E5%88%87%E6%8D%A2%22%5D%0A%20%20EFF%20--%3E%20DET%5B%22%E7%BB%86%E5%88%99%E6%97%A5%EF%BC%9A%E8%A7%A3%E9%87%8A%E7%A9%BA%E9%97%B4%E6%94%B6%E7%AA%84%22%5D%0A%20%20DET%20--%3E%20CH1%5B%22%E5%8F%82%E4%B8%8E%E9%9B%86%E5%90%88%EF%BC%9A%E8%B0%81%E5%9C%A8%E5%9C%BA%22%5D%0A%20%20DET%20--%3E%20CH2%5B%22%E4%BA%A4%E6%98%93%E6%8A%80%E6%9C%AF%EF%BC%9Atick%20%E8%B4%B9%E7%8E%87%20%E6%92%AE%E5%90%88%22%5D%0A%20%20DET%20--%3E%20CH3%5B%22%E5%A4%B4%E5%AF%B8%E7%BA%A6%E6%9D%9F%EF%BC%9A%E6%9D%A0%E6%9D%86%20%E5%8D%96%E7%A9%BA%20%E6%8C%81%E6%9C%89%E6%9C%9F%22%5D%0A%20%20DET%20--%3E%20CH4%5B%22%E4%BF%A1%E6%81%AF%E7%8E%AF%E5%A2%83%EF%BC%9A%E6%8A%AB%E9%9C%B2%E4%B9%89%E5%8A%A1%22%5D%0A%20%20CH1%20--%3E%20COEF%5B%22%E9%80%9F%E7%8E%87%E7%B3%BB%E6%95%B0%E5%8F%98%E5%8C%96%E8%A1%A8%22%5D%0A%20%20CH2%20--%3E%20COEF%0A%20%20CH3%20--%3E%20FEAS%5B%22%E7%BA%A6%E6%9D%9F%E5%8F%98%E5%8C%96%E8%A1%A8%EF%BC%9A%E5%8F%AF%E8%A1%8C%E6%80%A7%E4%B8%8E%E5%90%88%E8%A7%84%22%5D%0A%20%20CH4%20--%3E%20COEF%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t("h2",{id:"机制",tabindex:"-1"},[a("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=t("p",null,[a("制度事件的经济机制是"),t("strong",null,"改变均衡的条件而不是均衡的位置"),a("。做市商价差由逆向选择、存货与指令处理成本构成；tick 与费率动指令处理成本，撮合迁移动指令到达的相位，披露义务动逆向选择。预测系数变化的方向要用通道推，不用「好事坏事」推：同一项披露义务，对逆向选择是利好（信息更对称），对参与集合是利空（无力披露者退出），对价差的作用相反，净效应是实证问题。宣布与生效的分离还制造一段适应期：规则公开后、强制前，受影响者已在调整——过渡行为是机制假设最好的检验场，删掉它等于丢掉样本里最有信息的一段。")],-1)),(r(),B(s,null,{default:e(()=>[o(A,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20RULE%5B%22%E4%B8%80%E9%A1%B9%E6%96%B0%E6%8A%AB%E9%9C%B2%E4%B9%89%E5%8A%A1%22%5D%20--%3E%20CH1%5B%22%E4%BF%A1%E6%81%AF%E7%8E%AF%E5%A2%83%E9%80%9A%E9%81%93%3A%20%E9%80%86%E5%90%91%E9%80%89%E6%8B%A9%E4%B8%8B%E9%99%8D%22%5D%0A%20%20CH1%20--%3E%20P1%5B%22%E4%BB%B7%E5%B7%AE%E8%B6%8B%E7%AA%84%22%5D%0A%20%20RULE%20--%3E%20CH2%5B%22%E5%8F%82%E4%B8%8E%E9%9B%86%E5%90%88%E9%80%9A%E9%81%93%3A%20%E6%97%A0%E5%8A%9B%E6%8A%AB%E9%9C%B2%E8%80%85%E9%80%80%E5%87%BA%22%5D%0A%20%20CH2%20--%3E%20P2%5B%22%E6%B7%B1%E5%BA%A6%E4%B8%8B%E9%99%8D%20%E4%BB%B7%E5%B7%AE%E8%B6%8B%E5%AE%BD%22%5D%0A%20%20P1%20--%3E%20NET%5B%22%E5%87%80%E6%95%88%E5%BA%94%20%3D%20%E4%B8%A4%E8%82%A1%E5%8A%9B%E7%9B%B8%E6%8A%B5%22%5D%0A%20%20P2%20--%3E%20NET%0A%20%20NET%20--%3E%20EMP%5B%22%E6%96%B9%E5%90%91%E9%9D%A0%E9%80%9A%E9%81%93%E6%8E%A8%20%E5%87%80%E5%80%BC%E7%95%99%E7%BB%99%E5%AE%9E%E8%AF%81%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=n('<p><span class="marginnote">常见误区：用「利好/利空」直觉给制度效应定性。同一项披露义务，对信息环境是利好、对参与集合是利空，两条通道对价差的作用相反；单一归因和直觉定性都不成立，方向要沿通道推、净效应留给实证。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写合规规避——红线是另一门课的事；研究回答「规则改变了什么」，不回答「怎么在边缘行走」。一次性事件的推断天然脆弱：对照组若也间接受影响，对照失效，结论降级为描述。跨市场外推要重校准：同样的 tick 缩减在不同做市结构下方向都可能不同。宣布效应常被重大消息日污染（政策常随宏观事件发布），事件窗要剔除或控制共发事件，否则制度效应与宏观冲击分不开。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>制度事件改写规则本身：时间线三段，样本量为 1，靠机制证据不靠重复抽样。</li><li>四条作用通道：参与集合、交易技术、头寸约束、信息环境；复合通道必须拆开归因。</li><li>适用范围给出天然对照组；过渡期行为是最有信息的一段，不能从样本里删掉。</li><li>事件表输出两张表：速率系数表给研究，约束变化表给风控合规。</li><li>出处：Bushee and Leuz, <em>Journal of Accounting Research</em>, 2005；Leuz and Wysocki, <em>JAR</em>, 2016；微观协议见<a href="/quant/obd-eventstudy-micro">事件研究的微观版本</a>；Harris, <em>Trading and Exchanges</em>, 2003。</li></ul>',5))])}const f=i(p,[["render",u]]);export{F as __pageData,f as default};
